const title = $input.first().json.title || '';
const description = $input.first().json.description || '';

// Simple heuristic to break down mission
function breakdownMission(title, desc) {
  const tasks = [];

  if (title.toLowerCase().includes('learn') || desc.toLowerCase().includes('learn') || title.includes('یادگیری')) {
    tasks.push({ title: 'Research and gather resources', priority: 'high' });
    tasks.push({ title: 'Create study plan with milestones', priority: 'high' });
    tasks.push({ title: 'Practice daily - minimum 1 hour', priority: 'medium' });
    tasks.push({ title: 'Build a project to apply knowledge', priority: 'medium' });
    tasks.push({ title: 'Review and document learnings', priority: 'low' });
  } else if (title.toLowerCase().includes('trading') || title.includes('معامله')) {
    tasks.push({ title: 'Analyze market and define strategy', priority: 'high' });
    tasks.push({ title: 'Paper trade for 2 weeks', priority: 'high' });
    tasks.push({ title: 'Review performance and adjust', priority: 'medium' });
    tasks.push({ title: 'Go live with small size', priority: 'medium' });
  } else {
    tasks.push({ title: `Research: ${title}`, priority: 'high' });
    tasks.push({ title: 'Define clear milestones', priority: 'high' });
    tasks.push({ title: 'Execute first milestone', priority: 'medium' });
    tasks.push({ title: 'Track progress and adjust', priority: 'medium' });
  }

  return tasks;
}

const tasks = breakdownMission(title, description);

return [{
  json: {
    mission_id: $input.first().json.mission_id,
    title: title,
    description: description,
    tasks: tasks,
    tasks_count: tasks.length,
    created_at: new Date().toISOString()
  }
}];
